(() => {
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const STORAGE_KEY = 'levelUpData_v1';
const CATEGORIES = ['Estudos','Inglês','Programação','Exercícios','Pessoal','Leitura','Outro'];
const XP_DEFAULTS = {small:20, medium:50, important:100, dailyBonus:50};
const today = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const uid = () => (crypto?.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`);
const dateLabel = (d=today()) => new Date(`${d}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});
const minutes = t => { if(!t || !/^\d{2}:\d{2}$/.test(t)) return NaN; const [h,m]=t.split(':').map(Number); return h*60+m; };
const duration = (a,b) => Math.max(0, minutes(b)-minutes(a));
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultState = () => ({
 profile:{name:'Player One',englishLevel:'Iniciante',dailyEnglish:30,weeklyEnglish:210,dailyExercise:30},
 xp:0,level:1, streak:0, lastActive:null, xpValues:{...XP_DEFAULTS},
 activities:[], completions:[], englishLogs:[], codingProjects:[], technologies:['C','HTML','CSS','JavaScript'], exerciseLogs:[], missions:[], achievements:[], notified:[], preferences:{compact:false,sounds:true,volume:35,notificationSounds:true,animations:true,animationIntensity:'normal',notificationsEnabled:false,activityReminders:true,pendingAlerts:true,xpAlerts:true,reminderLead:0},
});
let state = loadState(), page='dashboard', statsRange='week';
function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY); if(raw){const x=JSON.parse(raw);return {...defaultState(),...x,profile:{...defaultState().profile,...x.profile},xpValues:{...XP_DEFAULTS,...x.xpValues},preferences:{...defaultState().preferences,...x.preferences}}}}catch(e){console.warn('Não foi possível carregar os dados:',e)}return defaultState()}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){toast('Erro ao salvar','O navegador não permitiu salvar os dados.','error')}}
function toast(title,msg='',type=''){const root=$('#toast-root');if(!root)return;const key=`${title}|${msg}`;if([...root.children].some(x=>x.dataset.key===key))return;const el=document.createElement('div');el.dataset.key=key;el.className=`toast toast-${type||'info'} ${type==='success'?'success':''}`;el.setAttribute('role',type==='error'?'alert':'status');el.innerHTML=`<button class="toast-dismiss" aria-label="Dispensar">×</button><strong>${esc(title)}</strong>${esc(msg)}`;root.append(el);el.querySelector('button').onclick=()=>el.remove();setTimeout(()=>el.remove(),4200)}
// Módulos centrais de áudio, feedback e notificações; sem áudio automático.
const AudioFX=(()=>{let ctx=null,last='';const patterns={click:[[760,.035,.025]],hover:[[500,.025,.012]],open:[[420,.04,.025],[680,.06,.025]],close:[[650,.04,.02],[390,.05,.02]],nav:[[440,.04,.02],[590,.05,.02]],toggle:[[560,.05,.025]],success:[[520,.06,.03],[760,.08,.035]],xp:[[660,.04,.025],[880,.06,.03],[1120,.07,.025]],level:[[440,.08,.035],[660,.09,.04],[880,.12,.04],[1175,.16,.035]],achievement:[[523,.07,.03],[659,.07,.03],[784,.12,.04]],error:[[260,.08,.025]],tutorial:[[600,.04,.02],[800,.05,.02]],notify:[[740,.07,.025],[980,.08,.02]]};function play(kind='click'){const p=state.preferences;if(!p?.sounds||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches&&kind==='hover')return;const now=performance.now();if(kind===last&&now-(play.t||0)<90)return;last=kind;play.t=now;try{ctx=ctx||new (window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();const vol=Math.max(0,Math.min(1,(Number(p.volume??35)/100)*.09));(patterns[kind]||patterns.click).forEach(([freq,dur,gain],i)=>{const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+i*(dur*.72);o.type=kind==='error'?'triangle':'sine';o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(80,freq*.78),t+dur);g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(vol*gain/.04,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+dur+.01)})}catch(e){/* áudio é melhoria opcional */}}return {play}})();
function applyExperiencePrefs(){const p=state.preferences||{};document.documentElement.classList.toggle('no-motion',!p.animations||p.animationIntensity==='reduced'||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches);document.documentElement.dataset.motion=p.animationIntensity||'normal'}
function nativeNotify(title,body,tag='level-up'){if(!state.preferences.notificationsEnabled||!('Notification'in window)||Notification.permission!=='granted')return false;try{new Notification(title,{body,tag,icon:'./icons/icon-192.png'});if(state.preferences.notificationSounds)AudioFX.play('notify');return true}catch(e){return false}}
function requestNotifications(){if(!('Notification'in window)){toast('Não compatível','Este navegador não oferece notificações nativas.','error');return}if(Notification.permission==='denied'){toast('Permissão bloqueada','Altere a permissão de notificações nas configurações do navegador.','error');return}Notification.requestPermission().then(permission=>{state.preferences.notificationsEnabled=permission==='granted';save();render();toast(permission==='granted'?'Notificações ativadas':'Permissão não concedida',permission==='granted'?'Você pode receber avisos enquanto o site estiver aberto.':'Você pode permitir depois nas configurações do navegador.',permission==='granted'?'success':'error')})}
function announce(title,body,type='info',tag='level-up'){toast(title,body,type);if(type==='success'&&state.preferences.xpAlerts)nativeNotify(title,body,tag)}
function checkNotifications(){if(!state.preferences.activityReminders)return;const now=new Date(),cur=now.getHours()*60+now.getMinutes(),lead=Math.max(0,Number(state.preferences.reminderLead)||0);state.activities.filter(a=>a.date===today()&&a.doneOn!==today()&&minutes(a.start)===cur+lead).forEach(a=>{const key=`${today()}-${a.id}-${a.start}-lead${lead}`;if(!state.notified.includes(key)){state.notified.push(key);const title=lead?`Atividade em ${lead} min`:'Hora da atividade',body=`${a.title} · ${a.start}–${a.end}`;toast(title,body,'info');nativeNotify(title,body,key);save()}})}
function xpForLevel(level){return 100*level}
function totalForNext(){return xpForLevel(state.level)}
function currentLevelXP(){let left=state.xp;let level=1;while(left>=xpForLevel(level)){left-=xpForLevel(level);level++}return {level,within:left,need:xpForLevel(level)}}
function updateLevel(){const info=currentLevelXP();if(info.level>state.level){state.level=info.level;$('#new-level').textContent=state.level;$('#level-overlay').hidden=false;checkAchievements();}else state.level=info.level}
function grantXP(amount,reason){const old=state.level;state.xp+=Math.max(0,Number(amount)||0);updateLevel();announce(`+${amount} XP`,reason,'success',`xp-${today()}-${state.xp}`);AudioFX.play(state.level>old?'level':'xp');save();renderSidebar();if(state.level>old)$('#level-overlay').hidden=false}
function completeActivity(id){const a=state.activities.find(x=>x.id===id);if(!a||a.doneOn===today()){toast('Tarefa já concluída','Ela não pode conceder XP novamente hoje.');return}a.doneOn=today();state.completions.push({id:uid(),activityId:a.id,title:a.title,category:a.category,date:today(),minutes:duration(a.start,a.end),xp:Number(a.xp)||0});updateStreak();grantXP(Number(a.xp)||0,`${a.title} concluída`);checkDailyBonus();checkAchievements();render()}
function updateStreak(){const dates=[...new Set(state.completions.map(x=>x.date).concat(state.englishLogs.map(x=>x.date),state.exerciseLogs.map(x=>x.date)))].sort().reverse();if(!dates.length){state.streak=0;state.lastActive=null;return}const d=new Date(`${dates[0]}T12:00:00`), t=new Date(`${today()}T12:00:00`);const diff=Math.round((t-d)/86400000);if(diff>1){state.streak=1}else if(state.lastActive!==dates[0]){state.streak=diff===0?Math.max(1,state.streak):1}state.lastActive=dates[0]}
function checkDailyBonus(){const todays=state.activities.filter(a=>a.date===today());if(todays.length&&todays.every(a=>a.doneOn===today())&&!state.completions.some(c=>c.date===today()&&c.bonus)){state.xp+=Number(state.xpValues.dailyBonus)||0;state.completions.push({id:uid(),date:today(),title:'Bônus de rotina completa',category:'Pessoal',minutes:0,xp:Number(state.xpValues.dailyBonus)||0,bonus:true});announce('Bônus diário!',`+${state.xpValues.dailyBonus} XP por concluir a rotina.`,'success','daily-bonus');AudioFX.play('achievement');updateLevel()}}
function checkAchievements(){const checks=[['first-task','Primeiro passo','Conclua sua primeira tarefa',state.completions.some(c=>!c.bonus)],['xp-500','Em ascensão','Acumule 500 XP',state.xp>=500],['english-7','Mente global','Registre estudos de inglês em 7 dias',new Set(state.englishLogs.map(x=>x.date)).size>=7],['coder','Construtor','Conclua seu primeiro projeto',state.codingProjects.some(p=>p.status==='Concluído')],['move-5','Em movimento','Registre 5 sessões de exercício',state.exerciseLogs.length>=5],['level-5','Elite','Alcance o nível 5',state.level>=5]];checks.forEach(([id,name,desc,ok])=>{if(ok&&!state.achievements.some(a=>a.id===id)){state.achievements.push({id,name,desc,date:today()});announce('Conquista desbloqueada',name,'success',`achievement-${id}`);AudioFX.play('achievement')}})}
function renderSidebar(){const n=state.profile.name||'Player One';$('#side-name').textContent=n;$('#top-name').textContent=n;$('#side-level').textContent=`NÍVEL ${state.level} · ${state.level<3?'RECRUTA':state.level<6?'EXPLORADOR':'ELITE'}`;$$('.avatar').forEach(x=>x.textContent=n.split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase()||'LV')}
function setPage(p){page=p;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#page-crumb').textContent=({dashboard:'DASHBOARD',routine:'MINHA ROTINA',english:'INGLÊS',coding:'PROGRAMAÇÃO',exercise:'EXERCÍCIOS',missions:'MISSÕES',stats:'ESTATÍSTICAS',settings:'CONFIGURAÇÕES'})[p]||'DASHBOARD';$('#sidebar').classList.remove('open');render()}
function head(kicker,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function stat(label,value,sub,icon){return `<div class="card stat-card"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div>`}
function empty(title,desc,button='',action=''){return `<div class="empty-state"><strong>${title}</strong>${desc}${button?`<div style="margin-top:14px"><button class="btn primary" data-action="${action}">${button}</button></div>`:''}</div>`}
function activityStatus(a){if(a.doneOn===today())return ['Concluída','done'];const now=new Date(),cur=now.getHours()*60+now.getMinutes(),s=minutes(a.start),e=minutes(a.end);if(a.date===today()&&cur>=s&&cur<e)return ['Em andamento','now'];if(a.date<today())return ['Pendente',''];if(a.date===today()&&cur>=e)return ['Pendente',''];return ['Pendente','upcoming']}
function activityCard(a){const [status,cls]=activityStatus(a);return `<div class="activity-row"><div class="activity-time">${esc(a.start)} – ${esc(a.end)}</div><span class="category-dot"></span><div class="activity-info"><strong>${esc(a.title)}</strong><small>${esc(a.category)} · ${Number(a.xp)||0} XP</small></div><span class="status ${cls}">${status}</span><div class="button-row"><button class="btn small" data-action="edit-activity" data-id="${a.id}" aria-label="Editar ${esc(a.title)}">Editar</button>${a.doneOn!==today()?`<button class="btn small primary" data-action="complete-activity" data-id="${a.id}">Concluir</button>`:'<span class="pill green">✓ Feita</span>'}<button class="btn small danger" data-action="delete-activity" data-id="${a.id}" aria-label="Excluir ${esc(a.title)}">×</button></div></div>`}
function getWeekDates(){const d=new Date();const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(d.getDate()+i);return x.toISOString().slice(0,10)})}
function miniChart(data,labels){const max=Math.max(1,...data);return `<div class="mini-chart">${data.map((v,i)=>`<div class="chart-bar-wrap" title="${v} XP"><div class="chart-bar" style="height:${Math.max(3,v/max*100)}%"></div><small>${labels[i]}</small></div>`).join('')}</div>`}
function weeklyXP(){const dates=getWeekDates();return dates.map(d=>state.completions.filter(c=>c.date===d).reduce((s,c)=>s+(Number(c.xp)||0),0))}
function nextActivity(){const now=new Date(),cur=now.getHours()*60+now.getMinutes();return state.activities.filter(a=>a.date===today()&&a.doneOn!==today()&&minutes(a.start)>=cur).sort((a,b)=>minutes(a.start)-minutes(b.start))[0]}
function renderDashboard(){const info=currentLevelXP(),tasks=state.completions.filter(c=>c.date===today()&&!c.bonus).length,totalTime=state.completions.filter(c=>c.date===today()).reduce((s,c)=>s+(c.minutes||0),0),todays=state.activities.filter(a=>a.date===today()).sort((a,b)=>a.start.localeCompare(b.start)),next=nextActivity(),week=weeklyXP();const hr=new Date().getHours();const greet=hr<12?'Bom dia':hr<18?'Boa tarde':'Boa noite';const progress=info.within/info.need*100;return `${head('SEU PAINEL DE CONTROLE',`${greet}, ${esc(state.profile.name)}.`,`Toda pequena ação conta. Continue construindo sua evolução.`,`<span class="date-label">${dateLabel()}</span>`)}
<div class="grid stats-grid">${stat('XP TOTAL',state.xp,'Experiência acumulada','✦')}${stat('SEQUÊNCIA ATIVA',`${state.streak} dia${state.streak===1?'':'s'}`,'Sem pressão: consistência no seu ritmo','↗')}${stat('TAREFAS CONCLUÍDAS',state.completions.filter(c=>c.date===today()&&!c.bonus).length,'Concluídas hoje','✓')}${stat('TEMPO REGISTRADO',`${Math.floor(totalTime/60)}h ${totalTime%60}m`,'Tempo de tarefas concluídas hoje','◷')}</div>
<div class="grid dashboard-grid"><div><div class="card hero-card"><div class="hero-top"><div><div class="eyebrow">STATUS DO JOGADOR</div><h2>Seu progresso, seu ritmo.</h2><p>Você não precisa vencer todos os dias. Só precisa continuar voltando para aquilo que importa.</p></div><div class="level-pill">LVL ${state.level}</div></div><div class="xp-row"><span>PROGRESSO PARA O NÍVEL ${state.level+1}</span><strong>${info.within} / ${info.need} XP</strong></div><div class="progress"><span style="width:${progress}%"></span></div><div class="hero-bottom"><div><strong>${state.xp}</strong>XP total</div><div><strong>${info.need-info.within}</strong>XP restantes</div><div><strong>${state.achievements.length}</strong>conquistas</div></div></div>
<div class="section-heading"><div><h2>Agenda de hoje</h2><p>Seu próximo passo começa aqui.</p></div><button class="text-link" data-action="go-routine">VER ROTINA ↗</button></div><div class="activity-list">${todays.length?todays.slice(0,5).map(activityCard).join(''):empty('Sua agenda está livre','Adicione atividades para planejar seu dia.','＋ Adicionar atividade','add-activity')}</div></div>
<div><div class="card"><div class="section-heading" style="margin:0 0 4px"><div><h2>Próxima atividade</h2><p>Um passo de cada vez.</p></div><span class="stat-icon">◷</span></div>${next?`<div style="padding:19px 0 12px"><span class="pill red">${esc(next.start)} – ${esc(next.end)}</span><h3 style="font:700 19px 'Space Grotesk';margin:14px 0 7px">${esc(next.title)}</h3><p style="font-size:11px;color:var(--muted);margin:0">${esc(next.category)} · Recompensa de ${next.xp} XP</p></div><button class="btn primary" style="width:100%;margin-top:8px" data-action="go-routine">ABRIR MINHA ROTINA →</button>`:`<div style="padding:18px 0 8px;color:var(--muted);font-size:12px;line-height:1.6">Nenhuma atividade futura para hoje. Planeje a próxima missão quando quiser.</div><button class="btn" style="width:100%;margin-top:8px" data-action="add-activity">＋ ADICIONAR ATIVIDADE</button>`}</div>
<div class="card" style="margin-top:16px"><div class="section-heading" style="margin:0"><div><h2>XP nesta semana</h2><p>Dados dos seus registros</p></div><span class="pill">7 DIAS</span></div>${miniChart(week,['SEG','TER','QUA','QUI','SEX','SÁB','DOM'])}<div class="chart-legend"><span>Total da semana</span><strong>${week.reduce((a,b)=>a+b,0)} XP</strong></div></div>
<div class="card" style="margin-top:16px"><div class="section-heading" style="margin:0 0 12px"><div><h2>Conquistas</h2><p>Marcos desbloqueados</p></div><span class="stat-icon">✧</span></div>${state.achievements.length?state.achievements.slice(-3).reverse().map(a=>`<div class="metric-line"><span>✦ ${esc(a.name)}</span><strong>${dateLabel(a.date)}</strong></div>`).join(''):empty('Sua primeira conquista espera','Complete tarefas e registre seu progresso.')}</div></div></div>`}
function renderRoutine(){const list=state.activities.filter(a=>a.date===today()).sort((a,b)=>a.start.localeCompare(b.start));const other=state.activities.filter(a=>a.date!==today()).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));return `${head('PLANEJAMENTO','Minha Rotina','Organize o dia com intenção. A conclusão sempre depende de você.','<button class="btn primary" data-action="add-activity">＋ Nova atividade</button>')}<div class="card"><div class="section-heading" style="margin-top:0"><div><h2>Hoje · ${dateLabel()}</h2><p>${list.filter(a=>a.doneOn===today()).length} de ${list.length} atividades concluídas</p></div><span class="pill red">${list.reduce((s,a)=>s+(Number(a.xp)||0),0)} XP planejados</span></div><div class="progress"><span style="width:${list.length?list.filter(a=>a.doneOn===today()).length/list.length*100:0}%"></span></div><div class="activity-list" style="margin-top:17px">${list.length?list.map(activityCard).join(''):empty('Nenhuma atividade planejada para hoje','Monte uma rotina que funcione para você.','＋ Criar atividade','add-activity')}</div></div><div class="section-heading"><div><h2>Outras datas</h2><p>Atividades futuras ou planejadas em outros dias.</p></div></div><div class="card"><div class="activity-list">${other.length?other.map(activityCard).join(''):empty('Nada agendado para outras datas','Atividades de outros dias aparecerão aqui.')}</div></div>`}
function renderEnglish(){const logs=state.englishLogs,minutesTotal=logs.reduce((s,x)=>s+(+x.minutes||0),0),lessons=logs.reduce((s,x)=>s+(+x.lessons||0),0),words=logs.reduce((s,x)=>s+(+x.words||0),0),days=new Set(logs.map(x=>x.date)).size;const last7=getWeekDates(),weekly=last7.map(d=>logs.filter(x=>x.date===d).reduce((s,x)=>s+(+x.minutes||0),0)),daily=logs.filter(x=>x.date===today()).reduce((s,x)=>s+(+x.minutes||0),0);const recent=[...logs].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);return `${head('SKILL TREE · IDIOMAS','Inglês','Registre o que você estudou. O nível informado é sua autoavaliação.','<button class="btn primary" data-action="add-english">＋ Registrar estudo</button>')}<div class="grid stats-grid">${stat('TEMPO TOTAL',`${Math.floor(minutesTotal/60)}h ${minutesTotal%60}m`,'Somente sessões registradas','◷')}${stat('LIÇÕES CONCLUÍDAS',lessons,'Registradas por você','✓')}${stat('PALAVRAS NOVAS',words,'Palavras informadas nos registros','Aa')}${stat('DIAS DE ESTUDO',days,'Dias com pelo menos um registro','◎')}</div><div class="grid two-col"><div class="card"><div class="english-hero"><div><div class="eyebrow">NÍVEL ATUAL</div><h2>${esc(state.profile.englishLevel)}</h2><p>Seu nível é autodeclarado. O LEVEL UP não realiza testes de fluência nem estima proficiência automaticamente.</p><button class="btn" data-action="edit-english-level">Alterar nível</button></div><div class="level-ring" style="--ring:${Math.min(100,minutesTotal/600*100)}%"><div><strong>${Math.min(100,Math.round(minutesTotal/600*100))}%</strong><small>META PESSOAL*</small></div></div></div><div class="metric-line"><span>Meta diária</span><strong>${state.profile.dailyEnglish} min</strong></div><div class="progress" style="margin-top:10px"><span style="width:${Math.min(100,daily/state.profile.dailyEnglish*100)}%"></span></div><div class="chart-legend"><span>Hoje: ${daily} min</span><span>${Math.max(0,state.profile.dailyEnglish-daily)} min restantes</span></div><p style="font-size:9px;color:#747481;margin-top:12px">*Indicador de tempo registrado em relação a 10 horas de estudo, não de fluência.</p></div><div class="card"><div class="section-heading" style="margin-top:0"><div><h2>Minutos por dia</h2><p>Semana atual</p></div></div>${miniChart(weekly,['SEG','TER','QUA','QUI','SEX','SÁB','DOM'])}<div class="chart-legend"><span>Meta semanal: ${state.profile.weeklyEnglish} min</span><strong>${weekly.reduce((a,b)=>a+b,0)} min</strong></div><div class="progress" style="margin-top:10px"><span style="width:${Math.min(100,weekly.reduce((a,b)=>a+b,0)/state.profile.weeklyEnglish*100)}%"></span></div></div></div><div class="section-heading"><div><h2>Histórico de estudos</h2><p>Registros adicionados por você.</p></div></div><div class="card table-wrap">${recent.length?`<table class="history-table"><thead><tr><th>DATA</th><th>ATIVIDADE</th><th>TEMPO</th><th>LIÇÕES</th><th>PALAVRAS</th><th></th></tr></thead><tbody>${recent.map(x=>`<tr><td>${dateLabel(x.date)}</td><td>${esc(x.title)}</td><td>${x.minutes} min</td><td>${x.lessons||0}</td><td>${x.words||0}</td><td><button class="btn small danger" data-action="delete-record" data-kind="english" data-id="${x.id}">Excluir</button></td></tr>`).join('')}</tbody></table>`:empty('Nenhum estudo registrado','Registre sua primeira sessão para começar a acompanhar sua evolução.','＋ Registrar estudo','add-english')}</div>`}
function renderCoding(){const projects=state.codingProjects,done=projects.filter(p=>p.status==='Concluído').length,mins=projects.reduce((s,p)=>s+(+p.minutes||0),0);return `${head('SKILL TREE · DESENVOLVIMENTO','Programação','Construa projetos, registre tecnologias e acompanhe as horas dedicadas.','<button class="btn primary" data-action="add-project">＋ Novo projeto</button>')}<div class="grid stats-grid">${stat('PROJETOS ATIVOS',projects.filter(p=>p.status!=='Concluído').length,'Em andamento','⌘')}${stat('PROJETOS CONCLUÍDOS',done,'Finalizados por você','✓')}${stat('HORAS REGISTRADAS',`${Math.floor(mins/60)}h ${mins%60}m`,'Tempo informado nos projetos','◷')}${stat('TECNOLOGIAS',state.technologies.length,'No seu repertório','⌁')}</div><div class="grid two-col"><div class="card"><div class="section-heading" style="margin-top:0"><div><h2>Projetos</h2><p>Seu laboratório de ideias.</p></div><button class="btn small" data-action="add-project">＋ Projeto</button></div><div class="activity-list">${projects.length?projects.map(p=>`<div class="activity-row"><span class="stat-icon">⌘</span><div class="activity-info"><strong>${esc(p.name)}</strong><small>${esc(p.language)} · ${esc(p.status)} · ${p.minutes||0} min</small>${p.goal?`<small>Meta: ${esc(p.goal)}</small>`:''}</div><button class="btn small" data-action="edit-project" data-id="${p.id}">Editar</button><button class="btn small danger" data-action="delete-project" data-id="${p.id}">×</button></div>`).join(''):empty('Nenhum projeto cadastrado','Adicione um projeto para acompanhar sua jornada.','＋ Novo projeto','add-project')}</div></div><div class="card"><div class="section-heading" style="margin-top:0"><div><h2>Tecnologias</h2><p>Adicione linguagens e ferramentas que está estudando.</p></div></div><div class="tag-list">${state.technologies.map(t=>`<span class="tag">${esc(t)} <button data-action="remove-tech" data-name="${esc(t)}" aria-label="Remover ${esc(t)}">×</button></span>`).join('')||'<span class="pill">Nenhuma tecnologia</span>'}</div><form id="tech-form" class="button-row" style="margin-top:16px"><input class="input" name="technology" placeholder="Ex.: Python, Git..." required maxlength="40" style="flex:1;min-width:100px"><button class="btn primary">Adicionar</button></form><div class="section-heading"><div><h2>Histórico de progresso</h2><p>Projetos concluídos desbloqueiam conquistas.</p></div></div>${done?`<div class="metric-line"><span>Projetos finalizados</span><strong>${done}</strong></div>`:empty('Ainda sem projetos concluídos','Ao finalizar um projeto, atualize seu status.')}</div></div>`}
function renderExercise(){const logs=state.exerciseLogs,mins=logs.reduce((s,x)=>s+(+x.minutes||0),0),week=getWeekDates(),weekly=week.map(d=>logs.filter(x=>x.date===d).reduce((s,x)=>s+(+x.minutes||0),0)),active=weekly.filter(x=>x>0).length;return `${head('SKILL TREE · BEM-ESTAR','Exercícios','A consistência também inclui descanso. Registre sessões sem pressão para fazer mais.','<button class="btn primary" data-action="add-exercise">＋ Registrar sessão</button>')}<div class="grid stats-grid">${stat('SESSÕES',logs.length,'Total de registros','↗')}${stat('TEMPO TOTAL',`${Math.floor(mins/60)}h ${mins%60}m`,'Duração informada','◷')}${stat('DIAS ATIVOS NA SEMANA',`${active}/7`,'Frequência, não obrigação','◎')}${stat('XP DA CATEGORIA',logs.reduce((s,x)=>s+(+x.xp||0),0),'XP registrado nesta área','✦')}</div><div class="grid two-col"><div class="card"><div class="section-heading" style="margin-top:0"><div><h2>Consistência semanal</h2><p>Minutos de atividade registrados</p></div><span class="pill">${active} dias ativos</span></div>${miniChart(weekly,['SEG','TER','QUA','QUI','SEX','SÁB','DOM'])}<p style="font-size:10px;color:var(--muted);line-height:1.6">Dias de descanso fazem parte de uma rotina sustentável. Este painel não penaliza dias sem exercício.</p></div><div class="card"><div class="section-heading" style="margin-top:0"><div><h2>Metas pessoais</h2><p>Referências editáveis por você</p></div><button class="btn small" data-action="edit-exercise-goal">Editar</button></div><div class="metric-line"><span>Meta de minutos por sessão</span><strong>${state.profile.dailyExercise} min</strong></div><div class="metric-line"><span>Meta semanal</span><strong>Flexível</strong></div><div class="empty-state" style="margin-top:15px">A meta é uma referência pessoal, não uma cobrança. Ajuste-a de acordo com suas necessidades.</div></div></div><div class="section-heading"><div><h2>Histórico de sessões</h2><p>Atividades registradas</p></div></div><div class="card table-wrap">${logs.length?`<table class="history-table"><thead><tr><th>DATA</th><th>ATIVIDADE</th><th>DURAÇÃO</th><th>XP</th><th></th></tr></thead><tbody>${[...logs].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${dateLabel(x.date)}</td><td>${esc(x.title)}</td><td>${x.minutes} min</td><td class="red-text">+${x.xp}</td><td><button class="btn small danger" data-action="delete-record" data-kind="exercise" data-id="${x.id}">Excluir</button></td></tr>`).join('')}</tbody></table>`:empty('Nenhuma sessão registrada','Quando fizer uma atividade, registre-a aqui.','＋ Registrar sessão','add-exercise')}</div>`}
function missionProgress(m){if(m.type==='tasks')return Math.min(m.target,state.completions.filter(c=>c.date>=missionStart(m.period)&&!c.bonus).length);if(m.type==='english')return Math.min(m.target,state.englishLogs.filter(x=>x.date>=missionStart(m.period)).reduce((s,x)=>s+(+x.minutes||0),0));if(m.type==='exercise')return Math.min(m.target,state.exerciseLogs.filter(x=>x.date>=missionStart(m.period)).length);if(m.type==='coding')return Math.min(m.target,state.codingProjects.filter(x=>x.status==='Concluído').length);return Math.min(m.target,Number(m.progress)||0)}
function missionStart(period){const d=new Date();if(period==='weekly')d.setDate(d.getDate()-6);return d.toISOString().slice(0,10)}
function renderMissions(){const missions=state.missions;return `${head('OBJETIVOS E RECOMPENSAS','Missões','Transforme intenções em objetivos claros e acompanhe seu progresso.','<button class="btn primary" data-action="add-mission">＋ Nova missão</button>')}<div class="grid feature-grid">${missions.length?missions.map(m=>{const prog=missionProgress(m),done=prog>=m.target||m.claimed;return `<div class="card mission-card"><div class="mission-top"><span class="pill ${done?'green':'red'}">${done?'✓ CONCLUÍDA':m.period==='daily'?'DIÁRIA':m.period==='weekly'?'SEMANAL':'PERSONALIZADA'}</span><span class="mission-reward">✦ ${m.xp} XP</span></div><h3>${esc(m.title)}</h3><p>${esc(m.description||'Missão pessoal')}</p><div class="goal-row"><div class="goal-row-head"><span>Progresso</span><strong>${prog} / ${m.target} ${esc(m.unit||'')}</strong></div><div class="progress"><span style="width:${Math.min(100,prog/m.target*100)}%"></span></div></div><div class="button-row" style="margin-top:auto">${done&&!m.claimed?`<button class="btn primary" data-action="claim-mission" data-id="${m.id}">Resgatar XP</button>`:done?'<span class="pill green">Recompensa resgatada</span>':m.type==='custom'?`<button class="btn" data-action="progress-mission" data-id="${m.id}">Atualizar progresso</button>`:''}<button class="btn small" data-action="edit-mission" data-id="${m.id}">Editar</button><button class="btn small danger" data-action="delete-mission" data-id="${m.id}">Excluir</button></div></div>`}).join(''):empty('Nenhuma missão ativa','Crie uma missão para definir seu próximo objetivo.','＋ Criar missão','add-mission')}</div><div class="card" style="margin-top:17px"><div class="section-heading" style="margin-top:0"><div><h2>Ideias de missão</h2><p>Use sugestões como ponto de partida, adaptando-as à sua rotina.</p></div></div><div class="button-row"><button class="btn" data-action="suggest-mission" data-template="english">Estudar inglês por 30 minutos</button><button class="btn" data-action="suggest-mission" data-template="tasks">Concluir 3 tarefas</button><button class="btn" data-action="suggest-mission" data-template="coding">Finalizar um projeto</button><button class="btn" data-action="suggest-mission" data-template="exercise">Registrar 2 sessões de exercício</button></div></div>`}
function aggregateByCategory(){const map={};state.completions.forEach(c=>map[c.category]=(map[c.category]||0)+(c.minutes||0));state.englishLogs.forEach(c=>map.Inglês=(map.Inglês||0)+(c.minutes||0));state.exerciseLogs.forEach(c=>map.Exercícios=(map.Exercícios||0)+(c.minutes||0));return map}
function renderStats(){const all=state.completions,week=getWeekDates(),xps=week.map(d=>all.filter(c=>c.date===d).reduce((s,c)=>s+(+c.xp||0),0)),cats=aggregateByCategory(),sum=Object.values(cats).reduce((a,b)=>a+b,0),count=all.filter(c=>!c.bonus).length;return `${head('ANÁLISE DE PROGRESSO','Estatísticas','Uma visão baseada nos dados que você registrou. Sem estimativas disfarçadas de fatos.','<select class="input" id="stats-range" style="width:auto"><option value="week">Esta semana</option><option value="month">Este mês</option><option value="all">Todo o período</option></select>')}<div class="grid stats-grid">${stat('XP TOTAL',state.xp,'Experiência acumulada','✦')}${stat('TAREFAS REGISTRADAS',count,'Conclusões sem bônus','✓')}${stat('TEMPO RASTREADO',`${Math.floor(sum/60)}h ${sum%60}m`,'Somando registros por categoria','◷')}${stat('CONQUISTAS',state.achievements.length,'Marcos desbloqueados','✧')}</div><div class="grid two-col"><div class="card"><div class="section-heading" style="margin-top:0"><div><h2>XP por dia</h2><p>Semana atual</p></div></div>${miniChart(xps,['SEG','TER','QUA','QUI','SEX','SÁB','DOM'])}<div class="chart-legend"><span>XP registrado</span><strong>${xps.reduce((a,b)=>a+b,0)} XP</strong></div></div><div class="card"><div class="section-heading" style="margin-top:0"><div><h2>Tempo por categoria</h2><p>Minutos dos registros disponíveis</p></div></div>${Object.keys(cats).length?`<div class="bar-chart">${Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="bar-line"><label>${esc(k)}</label><div class="progress"><span style="width:${sum?v/sum*100:0}%"></span></div><strong>${v} min</strong></div>`).join('')}</div>`:empty('Ainda sem dados','Conclua tarefas ou registre sessões para gerar estatísticas.')}</div></div><div class="card" style="margin-top:16px"><div class="section-heading" style="margin-top:0"><div><h2>Resumo por categoria</h2><p>Dados cumulativos de atividades, inglês e exercícios.</p></div></div>${Object.keys(cats).length?Object.entries(cats).map(([k,v])=>`<div class="metric-line"><span>${esc(k)}</span><strong>${Math.floor(v/60)}h ${v%60}m</strong></div>`).join(''):empty('Sem registros suficientes','Seus dados aparecerão aqui quando forem registrados.')}</div><div class="card" style="margin-top:16px"><div class="section-heading" style="margin-top:0"><div><h2>Conquistas desbloqueadas</h2><p>Marcos obtidos no seu percurso.</p></div></div>${state.achievements.length?state.achievements.map(a=>`<div class="metric-line"><span>✦ ${esc(a.name)} <small style="color:var(--muted)">— ${esc(a.desc)}</small></span><strong>${dateLabel(a.date)}</strong></div>`).join(''):empty('Nenhuma conquista ainda','Continue registrando seu progresso.','Ver missões','go-missions')}</div>`}
function renderSettings(){return `${head('CONTROLE DO SISTEMA','Configurações','Personalize sua experiência e gerencie seus dados locais.','')}<div class="card experience-settings"><div class="settings-section"><h3>Notificações e experiência</h3><p>Configure lembretes, sons e animações. A permissão do sistema só será solicitada quando você apertar o botão abaixo.</p></div><div class="settings-controls"><label class="setting-toggle"><span><b>Notificações do navegador</b><small id="notification-status">${('Notification' in window)?(Notification.permission==='granted'?'Permissão concedida':Notification.permission==='denied'?'Permissão negada':'Ainda não autorizado'):'Este navegador não oferece notificações'}</small></span><button class="btn small primary" data-action="enable-notifications">Ativar / verificar</button></label><label class="setting-toggle"><span><b>Lembretes de atividades</b><small>Enquanto o site estiver aberto</small></span><input type="checkbox" data-pref="activityReminders" ${state.preferences.activityReminders?'checked':''}></label><label class="setting-toggle"><span><b>Alertas de tarefas pendentes</b><small>Avisos internos, sem spam</small></span><input type="checkbox" data-pref="pendingAlerts" ${state.preferences.pendingAlerts?'checked':''}></label><label class="setting-toggle"><span><b>Alertas de XP e conquistas</b><small>Feedback de recompensas reais</small></span><input type="checkbox" data-pref="xpAlerts" ${state.preferences.xpAlerts?'checked':''}></label><div class="field"><label for="reminder-lead">Antecedência do lembrete</label><select id="reminder-lead" data-pref="reminderLead"><option value="0" ${Number(state.preferences.reminderLead)===0?'selected':''}>No horário</option><option value="5" ${Number(state.preferences.reminderLead)===5?'selected':''}>5 minutos antes</option><option value="10" ${Number(state.preferences.reminderLead)===10?'selected':''}>10 minutos antes</option><option value="15" ${Number(state.preferences.reminderLead)===15?'selected':''}>15 minutos antes</option></select></div><button class="btn" data-action="test-notification">Enviar notificação de teste</button><p class="settings-note">Notificações com o site fechado exigem Push API, service worker e servidor de envio. Este pacote inclui PWA e lembretes enquanto o site está aberto; push remoto ainda requer configuração de servidor.</p></div><div class="settings-section"><h3>Efeitos e animações</h3></div><div class="settings-controls"><label class="setting-toggle"><span><b>Efeitos sonoros</b><small>Áudio local gerado pela Web Audio API</small></span><input type="checkbox" data-pref="sounds" ${state.preferences.sounds?'checked':''}></label><label class="setting-toggle"><span><b>Sons de notificações</b><small>Separado dos sons de interface</small></span><input type="checkbox" data-pref="notificationSounds" ${state.preferences.notificationSounds?'checked':''}></label><div class="field"><label for="sound-volume">Volume: <span id="volume-value">${state.preferences.volume}%</span></label><input id="sound-volume" type="range" min="0" max="100" value="${state.preferences.volume}" data-pref="volume"></div><label class="setting-toggle"><span><b>Animações da interface</b><small>Respeita também o movimento reduzido do sistema</small></span><input type="checkbox" data-pref="animations" ${state.preferences.animations?'checked':''}></label><div class="field"><label for="animation-intensity">Intensidade das animações</label><select id="animation-intensity" data-pref="animationIntensity"><option value="reduced" ${state.preferences.animationIntensity==='reduced'?'selected':''}>Reduzida</option><option value="normal" ${state.preferences.animationIntensity==='normal'?'selected':''}>Normal</option><option value="intense" ${state.preferences.animationIntensity==='intense'?'selected':''}>Intensa</option></select></div><div class="button-row"><button class="btn" data-action="test-sound">Testar som</button><button class="btn" data-action="test-animation">Testar animação</button><button class="btn" data-action="reset-experience">Restaurar preferências</button></div></div></div><div class="grid two-col"><div class="card"><div class="settings-section"><h3>Perfil do jogador</h3><p>Nome e preferências de aprendizado.</p></div><form id="profile-form" class="form-grid"><div class="field full"><label for="profile-name">Nome exibido</label><input id="profile-name" name="name" maxlength="40" required value="${esc(state.profile.name)}"></div><div class="field"><label for="daily-english">Meta diária de inglês (min)</label><input id="daily-english" name="dailyEnglish" type="number" min="1" max="600" required value="${state.profile.dailyEnglish}"></div><div class="field"><label for="weekly-english">Meta semanal de inglês (min)</label><input id="weekly-english" name="weeklyEnglish" type="number" min="1" max="5000" required value="${state.profile.weeklyEnglish}"></div><div class="field"><label for="daily-exercise">Meta de exercício por sessão (min)</label><input id="daily-exercise" name="dailyExercise" type="number" min="1" max="300" required value="${state.profile.dailyExercise}"></div><div class="field"><label for="english-level">Nível de inglês (autoavaliação)</label><select id="english-level" name="englishLevel">${['Iniciante','Básico','Intermediário','Intermediário avançado','Avançado','Prefiro não definir'].map(x=>`<option ${state.profile.englishLevel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><button class="btn primary">Salvar perfil</button></div></form></div><div class="card"><div class="settings-section"><h3>Regras de XP</h3><p>Personalize as recompensas para tarefas e a rotina diária.</p></div><form id="xp-form" class="form-grid"><div class="field"><label for="xp-small">Tarefa pequena</label><input id="xp-small" name="small" type="number" min="0" max="10000" value="${state.xpValues.small}" required></div><div class="field"><label for="xp-medium">Tarefa média</label><input id="xp-medium" name="medium" type="number" min="0" max="10000" value="${state.xpValues.medium}" required></div><div class="field"><label for="xp-important">Tarefa importante</label><input id="xp-important" name="important" type="number" min="0" max="10000" value="${state.xpValues.important}" required></div><div class="field"><label for="xp-bonus">Bônus de rotina completa</label><input id="xp-bonus" name="dailyBonus" type="number" min="0" max="10000" value="${state.xpValues.dailyBonus}" required></div><div class="field full"><button class="btn primary">Salvar regras de XP</button></div></form></div></div><div class="card tutorial-settings-card" style="margin-top:16px"><div class="settings-section"><h3>Introdução ao LEVEL UP</h3><p>Reveja o tutorial interativo sempre que quiser. Isso não altera seu XP, nível ou registros.</p></div><button class="btn ghost-red" data-action="review-tutorial">↻ Rever tutorial</button></div><div class="card" style="margin-top:16px"><div class="settings-section"><h3>Backup e armazenamento</h3><p>Seus dados ficam no localStorage deste navegador e não são sincronizados automaticamente entre dispositivos. Exporte um backup para guardar uma cópia.</p></div><div class="button-row"><button class="btn primary" data-action="export">⇩ Exportar backup JSON</button><button class="btn" data-action="import">⇧ Importar backup JSON</button><input type="file" id="import-file" accept=".json,application/json" hidden><button class="btn danger" data-action="reset">Apagar todos os dados</button></div><div class="metric-line" style="margin-top:12px"><span>Chave local</span><strong>levelUpData_v1</strong></div><div class="metric-line"><span>Versão do esquema</span><strong>1.0</strong></div></div><div class="card" style="margin-top:16px"><div class="settings-section"><h3>Conquistas</h3><p>As medalhas são concedidas por marcos registrados, não por avaliações automáticas de habilidade.</p></div>${state.achievements.length?state.achievements.map(a=>`<div class="metric-line"><span>✦ ${esc(a.name)}</span><strong>${dateLabel(a.date)}</strong></div>`).join(''):empty('Nenhuma conquista desbloqueada','Sua evolução será registrada aqui conforme você avança.')}</div>`}
function render(){renderSidebar();applyExperiencePrefs();const views={dashboard:renderDashboard,routine:renderRoutine,english:renderEnglish,coding:renderCoding,exercise:renderExercise,missions:renderMissions,stats:renderStats,settings:renderSettings};$('#page-content').innerHTML=(views[page]||renderDashboard)();if(page==='stats')$('#stats-range').value=statsRange}
function modal(title,body,onSubmit,submitLabel='Salvar'){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="close-modal" type="button" data-close-modal>×</button></div><form id="modal-form">${body}<div class="modal-actions"><button type="button" class="btn" data-close-modal>Cancelar</button><button class="btn primary" type="submit">${submitLabel}</button></div></form></section></div>`;root.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>root.innerHTML=''));root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''});root.querySelector('#modal-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(onSubmit(fd)===false)return;root.innerHTML='';save();render()});const first=root.querySelector('input,select,textarea');if(first)first.focus()}
function field(label,name,type='text',value='',opts={}){const id='f-'+name;let input;if(type==='select')input=`<select id="${id}" name="${name}" ${opts.required===false?'':'required'}>${opts.options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;else if(type==='textarea')input=`<textarea id="${id}" name="${name}" ${opts.required===false?'':'required'} maxlength="${opts.maxlength||300}">${esc(value)}</textarea>`;else input=`<input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${opts.required===false?'':'required'} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.step?`step="${opts.step}"`:''} maxlength="${opts.maxlength||120}" placeholder="${esc(opts.placeholder||'')}">`;return `<div class="field ${opts.full?'full':''}"><label for="${id}">${label}</label>${input}</div>`}
function addActivity(existing=null){const a=existing||{};modal(existing?'Editar atividade':'Nova atividade',`<div class="form-grid">${field('Nome da atividade','title','text',a.title||'',{full:true,placeholder:'Ex.: Praticar programação'})}${field('Data','date','date',a.date||today())}${field('Categoria','category','select',a.category||'Estudos',{options:CATEGORIES.map(x=>({value:x,label:x}))})}${field('Início','start','time',a.start||'14:00')}${field('Término','end','time',a.end||'15:00')}${field('Recompensa em XP','xp','number',a.xp??state.xpValues.medium,{min:0,max:10000})}</div>`,fd=>{const title=fd.get('title').trim(),start=fd.get('start'),end=fd.get('end'),date=fd.get('date');if(!title||!date||minutes(end)<=minutes(start)){toast('Confira os campos','O término deve ser posterior ao início.');return false}const obj={id:a.id||uid(),title,date,category:fd.get('category'),start,end,xp:Number(fd.get('xp')),doneOn:a.doneOn||null};if(existing)state.activities=state.activities.map(x=>x.id===a.id?obj:x);else state.activities.push(obj);toast(existing?'Atividade atualizada':'Atividade adicionada',title,'success')})}
function addEnglish(){modal('Registrar estudo de inglês',`<div class="form-grid">${field('Atividade / lição','title','text','',{full:true,placeholder:'Ex.: Unidade 3, listening'})}${field('Data','date','date',today())}${field('Tempo estudado (min)','minutes','number','30',{min:1,max:1440})}${field('Lições concluídas','lessons','number','1',{min:0,max:100})}${field('Palavras novas','words','number','0',{min:0,max:10000})}${field('Observações','notes','textarea','',{full:true,required:false})}</div>`,fd=>{const m=Number(fd.get('minutes'));if(m<=0||!Number.isFinite(m)){toast('Tempo inválido','Informe uma duração positiva.');return false}const log={id:uid(),title:fd.get('title').trim(),date:fd.get('date'),minutes:m,lessons:Number(fd.get('lessons')),words:Number(fd.get('words')),notes:fd.get('notes')};state.englishLogs.push(log);const reward=Math.max(0,Math.floor(m/15)*5);grantXP(reward,'Estudo de inglês registrado');updateStreak();checkAchievements();toast('Estudo registrado',`${m} minutos adicionados.`,'success')})}
function addProject(existing=null){const p=existing||{};modal(existing?'Editar projeto':'Novo projeto',`<div class="form-grid">${field('Nome do projeto','name','text',p.name||'',{full:true})}${field('Linguagem / tecnologia','language','text',p.language||'C',{placeholder:'Ex.: C, JavaScript'})}${field('Status','status','select',p.status||'Em andamento',{options:['Planejado','Em andamento','Concluído'].map(x=>({value:x,label:x}))})}${field('Tempo dedicado (min)','minutes','number',p.minutes||0,{min:0,max:100000})}${field('Meta do projeto','goal','text',p.goal||'',{required:false,placeholder:'Ex.: Criar um jogo de terminal'})}</div>`,fd=>{const status=fd.get('status'),wasDone=p.status==='Concluído';const obj={id:p.id||uid(),name:fd.get('name').trim(),language:fd.get('language').trim(),status,minutes:Number(fd.get('minutes')),goal:fd.get('goal').trim()};if(existing)state.codingProjects=state.codingProjects.map(x=>x.id===p.id?obj:x);else state.codingProjects.push(obj);if(status==='Concluído'&&!wasDone){grantXP(state.xpValues.important,'Projeto concluído');checkAchievements()}toast('Projeto salvo',obj.name,'success')})}
function addExercise(){modal('Registrar sessão de exercício',`<div class="form-grid">${field('Atividade','title','text','',{full:true,placeholder:'Ex.: Caminhada, alongamento'})}${field('Data','date','date',today())}${field('Duração (min)','minutes','number','30',{min:1,max:1440})}${field('Observações','notes','textarea','',{full:true,required:false})}</div><p style="font-size:10px;color:var(--muted)">Uma sessão registrada concede XP. Dias de descanso não reduzem seu progresso.</p>`,fd=>{const m=Number(fd.get('minutes'));if(m<=0){toast('Duração inválida','Informe minutos maiores que zero.');return false}const xp=Math.max(10,Math.floor(m/15)*10);state.exerciseLogs.push({id:uid(),title:fd.get('title').trim(),date:fd.get('date'),minutes:m,notes:fd.get('notes'),xp});grantXP(xp,'Sessão de exercício registrada');updateStreak();checkAchievements();toast('Sessão registrada',`+${xp} XP`,'success')})}
function addMission(existing=null,template=null){const m=existing||{};const presets={english:{title:'Estudar inglês por 30 minutos',description:'Registrar tempo de estudo de inglês.',type:'english',target:30,unit:'minutos',period:'daily'},tasks:{title:'Concluir 3 tarefas',description:'Concluir atividades da rotina.',type:'tasks',target:3,unit:'tarefas',period:'daily'},coding:{title:'Finalizar um projeto',description:'Concluir um projeto de programação.',type:'coding',target:1,unit:'projeto',period:'weekly'},exercise:{title:'Registrar 2 sessões de exercício',description:'Movimentar-se e respeitar o descanso.',type:'exercise',target:2,unit:'sessões',period:'weekly'}};const v={...(template?presets[template]:{}),...m};modal(existing?'Editar missão':'Nova missão',`<div class="form-grid">${field('Nome da missão','title','text',v.title||'',{full:true})}${field('Descrição','description','textarea',v.description||'',{full:true,required:false})}${field('Tipo de progresso','type','select',v.type||'custom',{options:[['custom','Manual'],['tasks','Tarefas concluídas'],['english','Minutos de inglês'],['exercise','Sessões de exercício'],['coding','Projetos concluídos']].map(([value,label])=>({value,label}))})}${field('Período','period','select',v.period||'daily',{options:[['daily','Diária'],['weekly','Semanal'],['custom','Personalizada']].map(([value,label])=>({value,label}))})}${field('Meta numérica','target','number',v.target||1,{min:1,max:100000})}${field('Unidade','unit','text',v.unit||'unidades',{maxlength:30})}${field('Recompensa XP','xp','number',v.xp??state.xpValues.medium,{min:0,max:10000})}</div>`,fd=>{const obj={id:m.id||uid(),title:fd.get('title').trim(),description:fd.get('description').trim(),type:fd.get('type'),period:fd.get('period'),target:Number(fd.get('target')),unit:fd.get('unit'),xp:Number(fd.get('xp')),claimed:m.claimed||false,progress:m.progress||0};if(existing)state.missions=state.missions.map(x=>x.id===m.id?obj:x);else state.missions.push(obj);toast('Missão salva',obj.title,'success')})}
function doAction(btn){const a=btn.dataset.action,id=btn.dataset.id;switch(a){case'retry-render':try{render()}catch(e){console.error(e);toast('Erro ao renderizar','Consulte o console do navegador.','error')}break;case'enable-notifications':requestNotifications();break;case'test-notification':if(!state.preferences.notificationsEnabled){toast('Ative primeiro','Use Ativar / verificar para conceder permissão.');break}nativeNotify('LEVEL UP — Teste','Suas notificações estão configuradas.','test');toast('Teste enviado','Se permitido pelo navegador, o aviso apareceu no sistema.','success');break;case'test-sound':AudioFX.play('level');break;case'test-animation':{const c=$('.experience-settings');if(c){c.classList.remove('experience-pulse');void c.offsetWidth;c.classList.add('experience-pulse')}break}case'reset-experience':state.preferences={...defaultState().preferences};save();applyExperiencePrefs();render();toast('Preferências restauradas','As opções de experiência voltaram ao padrão.','success');break;case'add-activity':addActivity();break;case'edit-activity':addActivity(state.activities.find(x=>x.id===id));break;case'delete-activity':if(confirm('Excluir esta atividade?')){state.activities=state.activities.filter(x=>x.id!==id);save();render()}break;case'complete-activity':completeActivity(id);break;case'go-routine':setPage('routine');break;case'go-missions':setPage('missions');break;case'add-english':addEnglish();break;case'edit-english-level':modal('Nível de inglês',`<div class="field"><label for="f-level">Autoavaliação atual</label><select id="f-level" name="level">${['Iniciante','Básico','Intermediário','Intermediário avançado','Avançado','Prefiro não definir'].map(x=>`<option ${x===state.profile.englishLevel?'selected':''}>${x}</option>`).join('')}</select></div>`,fd=>{state.profile.englishLevel=fd.get('level')});break;case'add-project':addProject();break;case'edit-project':addProject(state.codingProjects.find(x=>x.id===id));break;case'delete-project':if(confirm('Excluir este projeto?')){state.codingProjects=state.codingProjects.filter(x=>x.id!==id);save();render()}break;case'remove-tech':state.technologies=state.technologies.filter(x=>x!==btn.dataset.name);save();render();break;case'add-exercise':addExercise();break;case'edit-exercise-goal':modal('Meta de exercício',field('Minutos por sessão','minutes','number',state.profile.dailyExercise,{min:1,max:300}),fd=>{state.profile.dailyExercise=Number(fd.get('minutes'))});break;case'add-mission':addMission();break;case'edit-mission':addMission(state.missions.find(x=>x.id===id));break;case'delete-mission':if(confirm('Excluir esta missão?')){state.missions=state.missions.filter(x=>x.id!==id);save();render()}break;case'suggest-mission':addMission(null,btn.dataset.template);break;case'claim-mission':{const m=state.missions.find(x=>x.id===id);if(m&&!m.claimed&&missionProgress(m)>=m.target){m.claimed=true;grantXP(m.xp,`Missão concluída: ${m.title}`);save();render()}break}case'progress-mission':{const m=state.missions.find(x=>x.id===id);if(m)modal('Atualizar progresso',field('Progresso atual','progress','number',m.progress||0,{min:0,max:m.target}),fd=>{m.progress=Math.min(m.target,Math.max(0,Number(fd.get('progress'))||0));if(m.progress>=m.target)toast('Meta alcançada','Você já pode resgatar a recompensa.','success')});break}case'delete-record':if(confirm('Excluir este registro? O XP já concedido não será removido automaticamente.')){const k=btn.dataset.kind==='english'?'englishLogs':'exerciseLogs';state[k]=state[k].filter(x=>x.id!==id);save();render()}break;case'review-tutorial':tutorialState.completed=false;tutorialState.introIndex=0;tutorialState.active=false;tutorialState.introActive=false;tutorialIntro();break;case'export':exportData();break;case'import':$('#import-file').click();break;case'reset':if(confirm('Isso apagará o progresso local. Exporte um backup antes, se quiser manter uma cópia. Continuar?')){localStorage.removeItem(STORAGE_KEY);state=defaultState();save();render();toast('Dados reiniciados','O sistema voltou ao estado inicial.')}break}}
function exportData(){const blob=new Blob([JSON.stringify({app:'LEVEL UP',version:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`level-up-backup-${today()}.json`;a.click();URL.revokeObjectURL(url);toast('Backup exportado','Guarde o arquivo em um local seguro.','success')}
function importData(file){const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),incoming=parsed.data||parsed;if(!incoming||!Array.isArray(incoming.activities)||!Array.isArray(incoming.completions))throw Error('Estrutura inválida');if(!confirm('Importar este backup substituirá os dados atuais. Deseja continuar?'))return;state={...defaultState(),...incoming,profile:{...defaultState().profile,...incoming.profile},xpValues:{...XP_DEFAULTS,...incoming.xpValues}};save();render();toast('Backup importado','Seus dados foram carregados.','success')}catch(e){toast('Falha ao importar','Arquivo inválido ou incompatível.')}$('#import-file').value=''};reader.readAsText(file)}
// Tutorial cinematicamente interativo. Todas as demonstrações são locais e fictícias.
const TUTORIAL_KEY='levelUpTutorial_v5';
const LEGACY_TUTORIAL_KEYS=['levelUpTutorial_v4','levelUpTutorial_v3','levelUpTutorial_v2','levelUpTutorial_v1'];
const TUTORIAL_STEPS=[
 {id:'dashboard',tag:'MISSÃO 01',title:'Conheça seu painel',desc:'Este é o seu centro de comando. Aqui você acompanha sua evolução.',art:'dashboard'},
 {id:'task',tag:'MISSÃO 02',title:'Crie sua primeira tarefa',desc:'Experimente criar uma tarefa fictícia. Ela não será salva na sua rotina real.',art:'task'},
 {id:'xp',tag:'MISSÃO 03',title:'Conquiste XP',desc:'Tarefas concluídas geram XP. Acumule experiência para subir de nível.',art:'xp'},
 {id:'skills',tag:'MISSÃO 04',title:'Desenvolva suas habilidades',desc:'Explore áreas diferentes e acompanhe cada tipo de prática.',art:'skills'},
 {id:'missions',tag:'MISSÃO 05',title:'Complete objetivos',desc:'Missões ajudam você a enxergar o próximo passo, sem exigir perfeição diária.',art:'missions'},
 {id:'stats',tag:'MISSÃO 06',title:'Veja sua evolução',desc:'Use tendências para entender seus hábitos. Estes números são apenas uma demonstração.',art:'stats'},
 {id:'final',tag:'MISSÃO FINAL',title:'Sua jornada começa',desc:'VOCÊ CONHECE O SISTEMA. AGORA É SUA VEZ DE EVOLUIR.',art:'final'}
];
function readTutorial(){
 const defaults={seen:false,completed:false,active:false,introActive:false,step:0,introIndex:0,introDone:false};
 try{
  const current=JSON.parse(localStorage.getItem(TUTORIAL_KEY)||'null');
  if(current&&typeof current==='object')return {...defaults,...current};
  // Migração segura: só considera concluído se uma versão anterior disser isso explicitamente.
  // Flags antigas como seen/introDone não bastam, pois também eram gravadas ao sair do tutorial.
  for(const key of LEGACY_TUTORIAL_KEYS){
   const legacy=JSON.parse(localStorage.getItem(key)||'null');
   if(legacy&&typeof legacy==='object'){
    const migrated={...defaults,...legacy,completed:legacy.completed===true,
      active:legacy.active===true,introActive:legacy.introActive===true,
      introDone:legacy.completed===true || legacy.introDone===true};
    if(migrated.completed){migrated.active=false;migrated.introActive=false;migrated.introDone=true;}
    localStorage.setItem(TUTORIAL_KEY,JSON.stringify(migrated));
    return migrated;
   }
  }
 }catch(e){console.warn('Não foi possível ler o estado do tutorial:',e)}
 return defaults;
}
let tutorialState=readTutorial();
function saveTutorial(){try{localStorage.setItem(TUTORIAL_KEY,JSON.stringify(tutorialState))}catch(e){console.warn('Não foi possível salvar o tutorial',e)}}
function startTutorial(){tutorialState={...tutorialState,seen:true,completed:false,active:true,introActive:false,step:0,introDone:true};saveTutorial();tutorialRender()}
function tutorialIntro(resume=false){const root=$('#tutorial-root');tutorialState={...tutorialState,seen:true,active:false,introActive:true,introDone:false,introIndex:resume?Math.max(0,Math.min(3,Number(tutorialState.introIndex)||0)):0};saveTutorial();document.body.classList.add('tutorial-is-open');root.innerHTML=`<div class="lu-intro" role="dialog" aria-modal="true" aria-label="Introdução LEVEL UP"><div class="lu-grid-bg"></div><div class="lu-intro-inner"><div class="lu-system-line"><span class="lu-live-dot"></span> SISTEMA ONLINE <span>BUILD 01.01</span></div><div class="lu-logo">LEVEL<span>UP</span><i>/// PERSONAL EVOLUTION SYSTEM</i></div><div class="lu-intro-copy" id="lu-intro-copy"><span class="lu-overline">INICIALIZANDO SUA JORNADA</span><h1>Todo mundo tem objetivos.</h1></div><div class="lu-intro-progress"><span id="lu-intro-bar"></span></div><div class="lu-intro-bottom"><span id="lu-intro-count">SEQUÊNCIA 01 / 04</span><span>FOCO · CONSISTÊNCIA · EVOLUÇÃO</span></div><div class="lu-intro-actions"><button class="lu-primary" data-tutorial="intro-next">INICIAR EXPERIÊNCIA <b>↗</b></button><button class="lu-text-btn" data-tutorial="skip-intro">PULAR INTRODUÇÃO</button></div></div></div>`;renderIntroFrame()}
const INTRO_LINES=['Todo mundo tem objetivos.','Poucos acompanham a própria evolução.','Chegou a hora de mudar isso.','SEU PRÓXIMO NÍVEL COMEÇA AGORA.'];
function renderIntroFrame(){const i=tutorialState.introIndex||0,copy=$('#lu-intro-copy');if(!copy)return;copy.classList.remove('lu-copy-in');copy.innerHTML=`<span class="lu-overline">${i===3?'PROTOCOLO DE EVOLUÇÃO PRONTO':'INICIALIZANDO SUA JORNADA'}</span><h1>${INTRO_LINES[i]}</h1>`;void copy.offsetWidth;copy.classList.add('lu-copy-in');$('#lu-intro-bar').style.width=`${(i+1)/4*100}%`;$('#lu-intro-count').textContent=`SEQUÊNCIA 0${i+1} / 04`;const btn=$('[data-tutorial="intro-next"]');btn.innerHTML=i===3?'INICIAR EXPERIÊNCIA <b>↗</b>':'CONTINUAR <b>→</b>';}
function tutorialEnd(completed=false){if(completed)AudioFX.play('achievement');tutorialState={...tutorialState,seen:true,completed:completed===true,active:false,introActive:false,step:0,introDone:completed===true};saveTutorial();$('#tutorial-root').innerHTML='';document.body.classList.remove('tutorial-is-open');setPage('dashboard');if(completed)toast('Jornada iniciada','Seu progresso real começa com suas próprias tarefas.','success')}
function demoArt(id){if(id==='dashboard')return `<div class="lu-demo-top"><span>PLAYER STATUS</span><b>LVL 01</b></div><div class="lu-demo-level">01 <small>NÍVEL INICIAL</small></div><div class="lu-demo-xp"><div><span>EXPERIÊNCIA</span><b><span class="lu-count" data-count="65">0</span> / 100 XP</b></div><div class="lu-meter"><i data-fill="65%"></i></div></div><div class="lu-demo-metrics"><div><b>01</b><small>PRÓXIMA ATIVIDADE</small><span>Estudar inglês</span></div><div><b>2/4</b><small>PROGRESSO DIÁRIO</small><span>Exemplo ilustrativo</span></div></div>`;
if(id==='task')return `<div class="lu-demo-top"><span>NOVA ATIVIDADE // SIMULAÇÃO</span><b>DEMO</b></div><div class="lu-task-form"><label>Nome da tarefa<input value="Estudar inglês" readonly></label><div class="lu-form-pair"><label>Categoria<input value="Inglês" readonly></label><label>Duração<input value="30 minutos" readonly></label></div><div class="lu-reward-row"><span>RECOMPENSA DE EXEMPLO</span><b>✦ 50 XP</b></div><button class="lu-primary lu-demo-action" data-tutorial="fake-task">＋ TESTAR CRIAÇÃO</button><p class="lu-demo-feedback" id="lu-demo-feedback">Aperte para simular. Nada será salvo na sua rotina real.</p></div>`;
if(id==='xp')return `<div class="lu-demo-top"><span>XP SIMULADO</span><b>SEM RECOMPENSA REAL</b></div><div class="lu-xp-gain">+<span id="lu-xp-number">0</span> <small>XP</small></div><div class="lu-xp-labels"><span>NÍVEL 1 → NÍVEL 2</span><b><span id="lu-xp-current">20</span> / 100 XP</b></div><div class="lu-meter lu-xp-meter"><i id="lu-xp-fill" style="width:20%"></i></div><button class="lu-primary lu-demo-action" data-tutorial="fake-xp">CONCLUIR TAREFA FICTÍCIA</button><p class="lu-demo-feedback">Os valores são ilustrativos e não alteram seu XP verdadeiro.</p>`;
if(id==='skills')return `<div class="lu-demo-top"><span>ÁREAS DE DESENVOLVIMENTO</span><b>DEMO</b></div><div class="lu-skill-grid"><button data-tutorial="skill-english" class="lu-skill-card"><span>◎</span><b>INGLÊS</b><small>Palavras · lições · tempo</small><i><em style="width:64%"></em></i></button><button data-tutorial="skill-code" class="lu-skill-card"><span>⌘</span><b>PROGRAMAÇÃO</b><small>Projetos · linguagens · prática</small><i><em style="width:42%"></em></i></button><button data-tutorial="skill-exercise" class="lu-skill-card"><span>↗</span><b>EXERCÍCIOS</b><small>Sessões · consistência</small><i><em style="width:78%"></em></i></button></div><div class="lu-skill-detail" id="lu-skill-detail">Selecione uma área para ver um exemplo de registro.</div>`;
if(id==='missions')return `<div class="lu-demo-top"><span>OBJETIVOS // DEMONSTRAÇÃO</span><b>EXEMPLO</b></div><div class="lu-mission-demo"><div><span>DIÁRIA</span><b>Dedique 30 min ao estudo</b><small>Recompensa ilustrativa: 20 XP</small><div class="lu-meter"><i id="lu-mission-fill" style="width:35%"></i></div></div><strong id="lu-mission-percent">35%</strong></div><div class="lu-mission-demo"><div><span>SEMANAL</span><b>Pratique 3 vezes</b><small>Progresso fictício · 1 de 3 sessões</small><div class="lu-meter"><i style="width:33%"></i></div></div><strong>1/3</strong></div><button class="lu-primary lu-demo-action" data-tutorial="fake-mission">AVANÇAR MISSÃO DE EXEMPLO</button><p class="lu-demo-feedback">Você pode ajustar seus objetivos ao seu ritmo. Não é preciso completar tudo todos os dias.</p>`;
if(id==='stats')return `<div class="lu-demo-top"><span>RELATÓRIO DE EVOLUÇÃO</span><b>DADOS FICTÍCIOS</b></div><div class="lu-chart-title">XP por dia <span>SEMANA DEMO</span></div><div class="lu-bars">${[28,44,35,72,52,88,61].map((n,i)=>`<div><i style="--bar:${n}%;animation-delay:${i*70}ms"></i><small>${['S','T','Q','Q','S','S','D'][i]}</small></div>`).join('')}</div><div class="lu-stat-chips"><span><b>12</b> tarefas concluídas</span><span><b>4h 30m</b> tempo dedicado</span><span><b>240 XP</b> XP demonstrativo</span></div><p class="lu-demo-feedback">Confira tempo por atividade, tarefas concluídas, XP conquistado e histórico. Seus dados reais só aparecem depois que você os registra.</p>`;
return `<div class="lu-final-emblem">✦</div><div class="lu-final-level">LVL <b>01</b><span>RECRUTA</span></div><div class="lu-meter lu-final-meter"><i style="width:38%"></i></div><p class="lu-final-caption">PROGRESSO DECORATIVO · 38%</p>`}
function tutorialRender(){const root=$('#tutorial-root'),step=TUTORIAL_STEPS[tutorialState.step]||TUTORIAL_STEPS[0],i=tutorialState.step+1;document.body.classList.add('tutorial-is-open');root.innerHTML=`<div class="lu-tour" role="dialog" aria-modal="true" aria-label="Tutorial LEVEL UP"><header class="lu-tour-header"><div class="lu-mini-logo">L<span>U</span><small>LEVEL UP</small></div><div class="lu-tour-progress"><span>PROTOCOLO DE INÍCIO</span><b>0${i} <small>/ 07 MISSÕES</small></b><div class="lu-meter"><i style="width:${i/7*100}%"></i></div></div><button class="lu-exit" data-tutorial="exit" aria-label="Sair do tutorial">×</button></header><main class="lu-tour-main"><section class="lu-tour-copy"><div class="lu-mission-tag"><span></span>${step.tag}</div><h1>${step.title}</h1><p>${step.desc}</p>${step.id==='task'?'<p class="lu-small-note">A demonstração é isolada: não cria tarefas nem concede XP.</p>':''}${step.id==='final'?'<h2 class="lu-final-message">VOCÊ CONHECE O SISTEMA.<br><span>AGORA É SUA VEZ DE EVOLUIR.</span></h2>':''}<div class="lu-tour-controls">${tutorialState.step>0?'<button class="lu-back" data-tutorial="previous">← VOLTAR</button>':'<button class="lu-back" data-tutorial="exit">SAIR</button>'}<button class="lu-primary" data-tutorial="next">${step.id==='final'?'ENTRAR NO LEVEL UP':'ENTENDI, CONTINUAR'} <b>→</b></button></div><div class="lu-tour-foot">ESC PARA SAIR <span>•</span> DEMONSTRAÇÕES NÃO AFETAM SEUS REGISTROS</div></section><section class="lu-demo-wrap"><div class="lu-demo-label"><span>◈</span> VISUALIZAÇÃO DO SISTEMA <b>AO VIVO / DEMO</b></div><div class="lu-demo-screen" id="lu-demo-screen">${demoArt(step.art)}</div><div class="lu-demo-index"><span>LEVEL UP // SIMULAÇÃO</span><span>0${i} — 07</span></div></section></main><footer class="lu-tour-footer"><span>● SISTEMA PRONTO</span><div>${TUTORIAL_STEPS.map((_,n)=>`<i class="${n===tutorialState.step?'active':n<tutorialState.step?'done':''}"></i>`).join('')}</div><span>YOUR NEXT LEVEL</span></footer></div>`;if(step.id==='dashboard')animateCounter();saveTutorial()}
function animateCounter(){const el=$('[data-count]');if(!el)return;let n=0;const tick=()=>{n=Math.min(65,n+5);el.textContent=n;if(n<65&&$('#tutorial-root').contains(el))setTimeout(tick,24)};tick()}
function tutorialNext(){AudioFX.play('tutorial');if(tutorialState.step<TUTORIAL_STEPS.length-1){tutorialState.step++;saveTutorial();tutorialRender()}else tutorialEnd(true)}
function tutorialPrevious(){AudioFX.play('tutorial');if(tutorialState.step>0){tutorialState.step--;saveTutorial();tutorialRender()}}
$('#tutorial-root').addEventListener('click',e=>{const b=e.target.closest('[data-tutorial]');if(!b)return;switch(b.dataset.tutorial){case'intro-next':if((tutorialState.introIndex||0)<3){tutorialState.introIndex++;saveTutorial();renderIntroFrame()}else startTutorial();break;case'skip-intro':startTutorial();break;case'next':tutorialNext();break;case'previous':tutorialPrevious();break;case'exit':tutorialEnd(false);break;case'fake-task':$('#lu-demo-feedback').textContent='✓ Tarefa fictícia criada na demonstração. Sua rotina real continua intacta.';b.textContent='✓ SIMULAÇÃO CONCLUÍDA';b.disabled=true;break;case'fake-xp':$('#lu-xp-number').textContent='50';$('#lu-xp-current').textContent='70';$('#lu-xp-fill').style.width='70%';b.textContent='✓ TAREFA DEMONSTRADA';b.disabled=true;break;case'fake-mission':$('#lu-mission-fill').style.width='70%';$('#lu-mission-percent').textContent='70%';b.textContent='✓ PROGRESSO DEMONSTRADO';break;case'skill-english':case'skill-code':case'skill-exercise':{const d={'skill-english':['INGLÊS','Exemplo: registrar 12 palavras novas e 30 minutos de lição.'],'skill-code':['PROGRAMAÇÃO','Exemplo: projeto em C, linguagem registrada e horas de prática.'],'skill-exercise':['EXERCÍCIOS','Exemplo: sessão de movimento e acompanhamento semanal.']}[b.dataset.tutorial];$('#lu-skill-detail').innerHTML=`<b>${d[0]}</b><span>${d[1]}</span><small>REGISTRO ILUSTRATIVO — NÃO SALVO</small>`;$$('.lu-skill-card').forEach(x=>x.classList.toggle('selected',x===b));break}}});
document.addEventListener('keydown',e=>{if(!tutorialState.active)return;if(e.key==='Escape'){e.preventDefault();tutorialEnd(false)}else if(e.key==='ArrowRight'&&$('#tutorial-root [data-tutorial="next"]')){e.preventDefault();tutorialNext()}else if(e.key==='ArrowLeft'&&$('#tutorial-root [data-tutorial="previous"]')){e.preventDefault();tutorialPrevious()}});
$('#navigation').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)setPage(b.dataset.page)});
$('#page-content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)doAction(b)});
$('#quick-add').addEventListener('click',()=>addActivity());
$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#edit-profile').addEventListener('click',()=>setPage('settings'));
$('#close-level').addEventListener('click',()=>$('#level-overlay').hidden=true);
$('#page-content').addEventListener('change',e=>{if(e.target.id==='stats-range'){statsRange=e.target.value;const all=state.completions;if(statsRange==='month'){const m=today().slice(0,7);const data=Array.from({length:new Date().getDate()},(_,i)=>{const d=`${m}-${String(i+1).padStart(2,'0')}`;return all.filter(c=>c.date===d).reduce((s,c)=>s+(+c.xp||0),0)});const el=$('.mini-chart');if(el){el.innerHTML=miniChart(data,data.map((_,i)=>i+1));$('.section-heading p')?.replaceChildren(document.createTextNode('Mês atual'))}}else if(statsRange==='all')toast('Período completo','Os indicadores cumulativos mostram todos os registros.');else render();}});
$('#page-content').addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();const fd=new FormData(e.target);state.profile.name=fd.get('name').trim();state.profile.dailyEnglish=Number(fd.get('dailyEnglish'));state.profile.weeklyEnglish=Number(fd.get('weeklyEnglish'));state.profile.dailyExercise=Number(fd.get('dailyExercise'));state.profile.englishLevel=fd.get('englishLevel');save();render();toast('Perfil salvo','Suas preferências foram atualizadas.','success')}if(e.target.id==='xp-form'){e.preventDefault();const fd=new FormData(e.target);for(const k of Object.keys(XP_DEFAULTS))state.xpValues[k]=Number(fd.get(k));save();render();toast('Regras de XP salvas','Novas recompensas usarão estes valores.','success')}if(e.target.id==='tech-form'){e.preventDefault();const input=e.target.elements.technology,v=input.value.trim();if(v&&!state.technologies.some(t=>t.toLowerCase()===v.toLowerCase()))state.technologies.push(v);else toast('Tecnologia já existe','Digite uma tecnologia nova.');save();render()}});
document.addEventListener('change',e=>{if(e.target?.id==='import-file'&&e.target.files?.[0])importData(e.target.files[0]);const el=e.target.closest('[data-pref]');if(el){const key=el.dataset.pref;state.preferences[key]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;save();applyExperiencePrefs();if(key==='volume'&&$('#volume-value'))$('#volume-value').textContent=`${state.preferences.volume}%`;if(key==='sounds'&&state.preferences.sounds)AudioFX.play('toggle');if(key==='animations')toast('Animações atualizadas',state.preferences.animations?'Movimentos ativados.':'Movimentos reduzidos.','success')}});
$('#page-content').addEventListener('input',e=>{if(e.target.id==='sound-volume'){state.preferences.volume=Number(e.target.value);save();$('#volume-value').textContent=`${e.target.value}%`}});
document.addEventListener('click',e=>{const b=e.target.closest('button, [role=button], .nav-item');if(!b||b.disabled||b.closest('#tutorial-root')||b.dataset.action==='test-sound')return;if(b.dataset.page)AudioFX.play('nav');else if(b.dataset.action?.startsWith('complete-')||b.dataset.action==='claim-mission')AudioFX.play('success');else if(b.matches('.btn.primary'))AudioFX.play('click');else if(b.matches('.btn, .icon-button, .mobile-menu'))AudioFX.play('click')});

function updateClock(){const d=new Date();const el=$('#clock');if(el)el.textContent=d.toLocaleTimeString('pt-BR',{hour12:false})}
function checkNotifications(){const now=new Date(),cur=now.getHours()*60+now.getMinutes();state.activities.filter(a=>a.date===today()&&a.doneOn!==today()&&minutes(a.start)===cur).forEach(a=>{const key=`${today()}-${a.id}-${a.start}`;if(!state.notified.includes(key)){state.notified.push(key);toast('Hora da atividade',`${a.title} começa agora.`);save()}})}
// A introdução é aberta antes da renderização inicial do painel para não depender dela.
// Assim, um erro pontual ao montar o Dashboard não impede o tutorial de aparecer.
updateLevel();
applyExperiencePrefs();
updateClock();
if('serviceWorker' in navigator && location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(e=>console.warn('PWA service worker indisponível:',e));
if(tutorialState.active){tutorialRender()}else if(tutorialState.introActive&&!tutorialState.completed){tutorialIntro(true)}else if(!tutorialState.completed){tutorialIntro()}
try { render(); } catch(err) { console.error('Falha ao renderizar a página inicial do LEVEL UP:',err); const root=$('#page-content');if(root)root.innerHTML='<section class="card render-error"><h2>O painel encontrou um erro</h2><p>Seus dados locais foram preservados. Tente carregar novamente.</p><button class="btn primary" data-action="retry-render">Tentar novamente</button></section>'; }
setInterval(updateClock,1000);setInterval(()=>{checkNotifications();if(!tutorialState.active&&(page==='dashboard'||page==='routine'))render()},20000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkNotifications()});
})();